use std::io::Write;
use super::contracts;
use crate::core::shared::display_width;

pub const checkpoint_schema_revision:u16=1;
pub const max_reply_effects:usize=16;pub const max_reply_effect_bytes:usize=256;pub const max_reply_effect_total_bytes:usize=4096;
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub enum FeedMode{NativeLive,TmuxLive,JournalReplay}
#[derive(Clone,Debug,Default,Eq,PartialEq)]pub struct ProtocolReply{pub bytes:Vec<u8>}
#[derive(Clone,Debug,Default,Eq,PartialEq)]pub struct FeedResult{pub stats:FeedStats,pub replies:Vec<ProtocolReply>,pub reply_bytes:usize}
#[derive(Clone,Copy,Debug,Default,Eq,PartialEq)]pub enum Color{#[default]Default,Indexed(u8),Rgb{r:u8,g:u8,b:u8}}
#[derive(Clone,Copy,Debug,Default,Eq,PartialEq)]pub struct StyleFlags{pub bold:bool,pub dim:bool,pub italic:bool,pub underline:bool,pub reverse:bool,pub strike:bool}
#[derive(Clone,Copy,Debug,Default,Eq,PartialEq)]pub struct Style{pub fg:Color,pub bg:Color,pub flags:StyleFlags,pub hyperlink_id:u32}
#[derive(Clone,Debug,Eq,PartialEq)]pub struct Cell{pub codepoint:char,pub width:u8,pub combining_suffix:Vec<u8>,pub style:Style}
impl Default for Cell{fn default()->Self{Self{codepoint:' ',width:1,combining_suffix:Vec::new(),style:Style::default()}}}
#[derive(Clone,Copy,Debug,Default,Eq,PartialEq)]pub struct FeedStats{pub max_row_touched:u16,pub scrolled:bool,pub scroll_rows:u16}
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub enum GridError{InvalidGridSize,InvalidEngineCheckpoint,UnsupportedEngineRevision,CheckpointTooLarge,ReplyLimit}
#[derive(Clone,Copy,Debug,Eq,PartialEq)]enum Parser{Normal,Escape,Csi,Osc,OscEsc,Dcs,DcsEsc}

#[derive(Clone,Debug,Eq,PartialEq)]pub struct Grid{pub rows:u16,pub cols:u16,pub cells:Vec<Cell>,pub cursor_row:u16,pub cursor_col:u16,pub autowrap:bool,pub pending_wrap:bool,pub cursor_visible:bool,pub cursor_shape:contracts::CursorShape,pub cursor_blinking:bool,pub origin_mode:bool,pub insert_mode:bool,pub bracketed_paste:bool,pub mouse_modes:u16,pub focus_tracking:bool,pub application_cursor_keys:bool,pub application_keypad:bool,pub keyboard_protocol:bool,pub sync_active:bool,pub current_style:Style,parser:Parser,csi:Vec<u8>,string:Vec<u8>,utf8:Vec<u8>,saved_cursor:Option<(u16,u16,Style)>,saved_normal_screen:Option<Box<Grid>>}
impl Grid{
 pub fn init(cols:u16,rows:u16)->Result<Self,GridError>{let n=(cols as usize).checked_mul(rows as usize).ok_or(GridError::InvalidGridSize)?;if cols==0||rows==0||n>contracts::max_render_cells{return Err(GridError::InvalidGridSize)}Ok(Self{rows,cols,cells:vec![Cell::default();n],cursor_row:1,cursor_col:1,autowrap:true,pending_wrap:false,cursor_visible:true,cursor_shape:contracts::CursorShape::Block,cursor_blinking:true,origin_mode:false,insert_mode:false,bracketed_paste:false,mouse_modes:0,focus_tracking:false,application_cursor_keys:false,application_keypad:false,keyboard_protocol:false,sync_active:false,current_style:Style::default(),parser:Parser::Normal,csi:Vec::new(),string:Vec::new(),utf8:Vec::new(),saved_cursor:None,saved_normal_screen:None})}
 fn idx(&self,r:u16,c:u16)->usize{(r as usize-1)*self.cols as usize+c as usize-1}
 pub fn cell_at(&self,row:u16,col:u16)->Option<&Cell>{if row==0||row>self.rows||col==0||col>self.cols{None}else{Some(&self.cells[self.idx(row,col)])}}
 pub fn resize(&mut self,cols:u16,rows:u16)->Result<(),GridError>{let mut n=Self::init(cols,rows)?;for r in 1..=rows.min(self.rows){for c in 1..=cols.min(self.cols){let a=self.idx(r,c);let b=n.idx(r,c);n.cells[b]=self.cells[a].clone()}}n.cursor_row=self.cursor_row.min(rows);n.cursor_col=self.cursor_col.min(cols);n.current_style=self.current_style;n.autowrap=self.autowrap;*self=n;Ok(())}
 fn blank(&self)->Cell{Cell{style:Style{bg:self.current_style.bg,..Style::default()},..Cell::default()}}
 fn scroll(&mut self){let cols=self.cols as usize;let blank=self.blank();self.cells.drain(..cols);self.cells.extend((0..cols).map(|_|blank.clone()));}
 fn newline(&mut self,stats:&mut FeedStats){self.pending_wrap=false;self.cursor_col=1;if self.cursor_row==self.rows{self.scroll();stats.scrolled=true;stats.scroll_rows+=1}else{self.cursor_row+=1}stats.max_row_touched=stats.max_row_touched.max(self.cursor_row)}
 fn put_char(&mut self,ch:char,stats:&mut FeedStats){let mut buf=[0;4];let bytes=ch.encode_utf8(&mut buf).as_bytes();let width=display_width::visible_width(bytes).min(2) as u8;if width==0{if let Some(i)=self.last_lead(){self.cells[i].combining_suffix.extend_from_slice(bytes)}return}if self.pending_wrap&&self.autowrap{self.cursor_col=1;self.newline(stats)}self.pending_wrap=false;if width==2&&self.cursor_col==self.cols{if self.autowrap{self.cursor_col=1;self.newline(stats)}else{return}}let idx=self.idx(self.cursor_row,self.cursor_col);if self.cells[idx].width==0&&idx>0{self.cells[idx-1]=self.blank()}if self.cells[idx].width==2&&idx+1<self.cells.len(){self.cells[idx+1]=self.blank()}self.cells[idx]=Cell{codepoint:ch,width,combining_suffix:Vec::new(),style:self.current_style};if width==2{self.cells[idx+1]=Cell{codepoint:'\0',width:0,combining_suffix:Vec::new(),style:self.current_style}}stats.max_row_touched=stats.max_row_touched.max(self.cursor_row);let end=self.cursor_col+width as u16-1;if end>=self.cols{self.cursor_col=self.cols;self.pending_wrap=self.autowrap}else{self.cursor_col=end+1}}
 fn last_lead(&self)->Option<usize>{let idx=self.idx(self.cursor_row,self.cursor_col);if self.pending_wrap{Some(idx)}else if idx>0{Some(idx-1)}else{None}}
 pub fn feed(&mut self,bytes:&[u8])->Result<(),GridError>{self.feed_mode(bytes,FeedMode::JournalReplay).map(|_|())}
 pub fn feed_with_stats(&mut self,bytes:&[u8],stats:&mut FeedStats)->Result<(),GridError>{*stats=self.feed_mode(bytes,FeedMode::JournalReplay)?.stats;Ok(())}
 pub fn feed_mode(&mut self,bytes:&[u8],mode:FeedMode)->Result<FeedResult,GridError>{let mut result=FeedResult::default();for &b in bytes{match self.parser{Parser::Normal=>match b{0x1b=>self.parser=Parser::Escape,b'\n'=>self.newline(&mut result.stats),b'\r'=>{self.cursor_col=1;self.pending_wrap=false},8=>{self.cursor_col=self.cursor_col.saturating_sub(1).max(1);self.pending_wrap=false},b'\t'=>{self.cursor_col=(((self.cursor_col-1)/8+1)*8+1).min(self.cols);self.pending_wrap=false},0x18|0x1a=>{},0x20..=0x7e=>self.put_char(b as char,&mut result.stats),0x80..=0xff=>{self.utf8.push(b);if let Ok(s)=std::str::from_utf8(&self.utf8){if let Some(ch)=s.chars().next(){self.put_char(ch,&mut result.stats);self.utf8.clear()}}else if self.utf8.len()==4{self.utf8.clear()}},_=>{}},Parser::Escape=>{match b{b'['=>{self.csi.clear();self.parser=Parser::Csi},b']'=>{self.string.clear();self.parser=Parser::Osc},b'P'=>{self.string.clear();self.parser=Parser::Dcs},b'7'=>{self.saved_cursor=Some((self.cursor_row,self.cursor_col,self.current_style));self.parser=Parser::Normal},b'8'=>{if let Some((r,c,s))=self.saved_cursor{self.cursor_row=r;self.cursor_col=c;self.current_style=s}self.parser=Parser::Normal},b'D'=>{self.newline(&mut result.stats);self.parser=Parser::Normal},b'M'=>{self.cursor_row=self.cursor_row.saturating_sub(1).max(1);self.parser=Parser::Normal},_=>self.parser=Parser::Normal}},Parser::Csi=>{if (0x40..=0x7e).contains(&b){let seq=self.csi.clone();self.apply_csi(&seq,b,mode,&mut result)?;self.parser=Parser::Normal}else if self.csi.len()<64{self.csi.push(b)}else{self.parser=Parser::Normal}},Parser::Osc=>{if b==7{self.apply_osc();self.parser=Parser::Normal}else if b==0x1b{self.parser=Parser::OscEsc}else if self.string.len()<4096{self.string.push(b)}},Parser::OscEsc=>{if b==b'\\'{self.apply_osc();self.parser=Parser::Normal}else{self.parser=Parser::Osc}},Parser::Dcs=>{if b==0x1b{self.parser=Parser::DcsEsc}else if self.string.len()<4096{self.string.push(b)}},Parser::DcsEsc=>{self.parser=if b==b'\\'{Parser::Normal}else{Parser::Dcs}}}}Ok(result)}
 fn params(seq:&[u8])->Vec<u16>{let s=std::str::from_utf8(seq).unwrap_or("").trim_start_matches(['?','>']);if s.is_empty(){vec![0]}else{s.split(';').take(16).map(|x|x.parse().unwrap_or(0)).collect()}}
 fn apply_csi(&mut self,seq:&[u8],final_b:u8,mode:FeedMode,result:&mut FeedResult)->Result<(),GridError>{let p=Self::params(seq);let n=|i:usize,d:u16|p.get(i).copied().filter(|&x|x!=0).unwrap_or(d);match final_b{b'H'|b'f'=>{self.cursor_row=n(0,1).min(self.rows);self.cursor_col=n(1,1).min(self.cols);self.pending_wrap=false},b'A'=>self.cursor_row=self.cursor_row.saturating_sub(n(0,1)).max(1),b'B'=>self.cursor_row=(self.cursor_row+n(0,1)).min(self.rows),b'C'=>self.cursor_col=(self.cursor_col+n(0,1)).min(self.cols),b'D'=>self.cursor_col=self.cursor_col.saturating_sub(n(0,1)).max(1),b'G'=>self.cursor_col=n(0,1).min(self.cols),b'd'=>self.cursor_row=n(0,1).min(self.rows),b'J'=>self.erase_display(p[0]),b'K'=>self.erase_line(p[0]),b'm'=>self.sgr(&p),b'h'|b'l' if seq.first()==Some(&b'?')=>{let on=final_b==b'h';for x in p{match x{1=>self.application_cursor_keys=on,7=>self.autowrap=on,25=>self.cursor_visible=on,1000|1002|1003|1006=>self.mouse_modes=if on{1}else{0},1004=>self.focus_tracking=on,1049=>self.alternate(on),2004=>self.bracketed_paste=on,2026=>self.sync_active=on,_=>{}}}},b'h'|b'l'=>{if p.contains(&4){self.insert_mode=final_b==b'h'}},b'n' if p[0]==6&&mode==FeedMode::NativeLive=>{let bytes=format!("\x1b[{};{}R",self.cursor_row,self.cursor_col).into_bytes();if result.replies.len()>=max_reply_effects||result.reply_bytes+bytes.len()>max_reply_effect_total_bytes{return Err(GridError::ReplyLimit)}result.reply_bytes+=bytes.len();result.replies.push(ProtocolReply{bytes})},b's'=>self.saved_cursor=Some((self.cursor_row,self.cursor_col,self.current_style)),b'u'=>if let Some((r,c,s))=self.saved_cursor{self.cursor_row=r;self.cursor_col=c;self.current_style=s},_=>{}}Ok(())}
 fn erase_line(&mut self,mode:u16){let (a,b)=match mode{1=>(1,self.cursor_col),2=>(1,self.cols),_=>(self.cursor_col,self.cols)};for c in a..=b{let i=self.idx(self.cursor_row,c);self.cells[i]=self.blank()}}
 fn erase_display(&mut self,mode:u16){match mode{2|3=>{let blank=self.blank();self.cells.fill(blank)},1=>{for r in 1..=self.cursor_row{let end=if r==self.cursor_row{self.cursor_col}else{self.cols};for c in 1..=end{let i=self.idx(r,c);self.cells[i]=self.blank()}}},_=>{for r in self.cursor_row..=self.rows{let start=if r==self.cursor_row{self.cursor_col}else{1};for c in start..=self.cols{let i=self.idx(r,c);self.cells[i]=self.blank()}}}}}
 fn sgr(&mut self,p:&[u16]){let p=if p.is_empty(){&[0][..]}else{p};let mut i=0;while i<p.len(){match p[i]{0=>self.current_style=Style::default(),1=>self.current_style.flags.bold=true,2=>self.current_style.flags.dim=true,3=>self.current_style.flags.italic=true,4=>self.current_style.flags.underline=true,7=>self.current_style.flags.reverse=true,9=>self.current_style.flags.strike=true,22=>{self.current_style.flags.bold=false;self.current_style.flags.dim=false},23=>self.current_style.flags.italic=false,24=>self.current_style.flags.underline=false,27=>self.current_style.flags.reverse=false,29=>self.current_style.flags.strike=false,30..=37=>self.current_style.fg=Color::Indexed((p[i]-30)as u8),39=>self.current_style.fg=Color::Default,40..=47=>self.current_style.bg=Color::Indexed((p[i]-40)as u8),49=>self.current_style.bg=Color::Default,90..=97=>self.current_style.fg=Color::Indexed((p[i]-90+8)as u8),100..=107=>self.current_style.bg=Color::Indexed((p[i]-100+8)as u8),38|48 if i+2<p.len()&&p[i+1]==5=>{let c=Color::Indexed(p[i+2].min(255)as u8);if p[i]==38{self.current_style.fg=c}else{self.current_style.bg=c}i+=2},38|48 if i+4<p.len()&&p[i+1]==2=>{let c=Color::Rgb{r:p[i+2].min(255)as u8,g:p[i+3].min(255)as u8,b:p[i+4].min(255)as u8};if p[i]==38{self.current_style.fg=c}else{self.current_style.bg=c}i+=4},_=>{}}i+=1}}
 fn apply_osc(&mut self){if self.string.starts_with(b"8;"){let mut parts=self.string.splitn(3,|&b|b==b';');let _=parts.next();let _=parts.next();self.current_style.hyperlink_id=if parts.next().is_some_and(|u|!u.is_empty()){1}else{0}}self.string.clear()}
 fn alternate(&mut self,on:bool){if on&&self.saved_normal_screen.is_none(){if let Ok(mut alt)=Grid::init(self.cols,self.rows){std::mem::swap(self,&mut alt);self.saved_normal_screen=Some(Box::new(alt))}}else if !on{if let Some(mut normal)=self.saved_normal_screen.take(){std::mem::swap(self,&mut normal)}}}
 pub fn row_text(&self,row:u16)->Vec<u8>{let mut out=Vec::new();if row==0||row>self.rows{return out}for c in 1..=self.cols{let x=self.cell_at(row,c).unwrap();if x.width>0{let mut b=[0;4];out.extend_from_slice(x.codepoint.encode_utf8(&mut b).as_bytes());out.extend_from_slice(&x.combining_suffix)}}out}
 pub fn row_text_trimmed(&self,row:u16)->Vec<u8>{let mut x=self.row_text(row);while x.last()==Some(&b' '){x.pop();}x}
 pub fn render_snapshot(&self)->Result<contracts::OwnedRenderSnapshot,contracts::Error>{let cells=self.cells.iter().map(|c|contracts::RenderCell{kind:if c.width==0{contracts::CellKind::Continuation}else if c.width==2{contracts::CellKind::Wide}else if c.codepoint==' '&&c.combining_suffix.is_empty(){contracts::CellKind::Blank}else{contracts::CellKind::Single},text:if c.width==0||c.codepoint==' '&&c.combining_suffix.is_empty(){Vec::new()}else{let mut b=[0;4];let mut v=c.codepoint.encode_utf8(&mut b).as_bytes().to_vec();v.extend_from_slice(&c.combining_suffix);v},style:render_style(c.style)}).collect();let s=contracts::RenderSnapshot{dimensions:contracts::Dimensions{rows:self.rows,columns:self.cols},cursor:contracts::RenderCursor{row:self.cursor_row-1,column:self.cursor_col-1,visible:self.cursor_visible,shape:self.cursor_shape,blinking:self.cursor_blinking},modes:contracts::TerminalModes{alternate_screen:self.saved_normal_screen.is_some(),origin:self.origin_mode,autowrap:self.autowrap,insert:self.insert_mode,bracketed_paste:self.bracketed_paste,mouse_tracking:self.mouse_modes!=0,focus_tracking:self.focus_tracking,application_cursor_keys:self.application_cursor_keys,application_keypad:self.application_keypad,keyboard_protocol:self.keyboard_protocol,synchronized_updates:self.sync_active},cells};s.validate()?;Ok(s)}
 pub fn checkpoint_payload(&self)->Result<Vec<u8>,GridError>{let mut v=b"FXTE".to_vec();v.extend_from_slice(&checkpoint_schema_revision.to_le_bytes());v.extend_from_slice(&self.cols.to_le_bytes());v.extend_from_slice(&self.rows.to_le_bytes());v.extend_from_slice(&self.cursor_row.to_le_bytes());v.extend_from_slice(&self.cursor_col.to_le_bytes());for c in &self.cells{v.extend_from_slice(&(c.codepoint as u32).to_le_bytes());v.push(c.width)}Ok(v)}
 pub fn restore_checkpoint(payload:&[u8])->Result<Self,GridError>{if payload.len()>contracts::max_checkpoint_payload_bytes{return Err(GridError::CheckpointTooLarge)}if payload.len()<14||&payload[..4]!=b"FXTE"{return Err(GridError::InvalidEngineCheckpoint)}if u16::from_le_bytes(payload[4..6].try_into().unwrap())!=checkpoint_schema_revision{return Err(GridError::UnsupportedEngineRevision)}let cols=u16::from_le_bytes(payload[6..8].try_into().unwrap());let rows=u16::from_le_bytes(payload[8..10].try_into().unwrap());let mut g=Self::init(cols,rows)?;g.cursor_row=u16::from_le_bytes(payload[10..12].try_into().unwrap());g.cursor_col=u16::from_le_bytes(payload[12..14].try_into().unwrap());if payload.len()!=14+g.cells.len()*5{return Err(GridError::InvalidEngineCheckpoint)}for(i,ch)in payload[14..].chunks_exact(5).enumerate(){g.cells[i].codepoint=char::from_u32(u32::from_le_bytes(ch[..4].try_into().unwrap())).ok_or(GridError::InvalidEngineCheckpoint)?;g.cells[i].width=ch[4]}Ok(g)}
 pub fn diff_to(&self,next:&Grid,out:&mut impl Write)->std::io::Result<()>{Self::diff_band(self,next,1,next.rows,out)}
 pub fn diff_band(prev:&Grid,next:&Grid,top:u16,bottom:u16,out:&mut impl Write)->std::io::Result<()>{for r in top.max(1)..=bottom.min(next.rows){if (1..=next.cols).any(|c|prev.cell_at(r,c)!=next.cell_at(r,c)){write!(out,"\x1b[{r};1H")?;out.write_all(&next.row_text(r))?}}Ok(())}
 pub fn snapshot(&self)->Vec<u8>{let mut v=Vec::new();for r in 1..=self.rows{v.extend(self.row_text(r));if r<self.rows{v.push(b'\n')}}v}
 pub fn at_control_sequence_boundary(&self)->bool{self.parser==Parser::Normal&&self.utf8.is_empty()}
}
fn render_style(s:Style)->contracts::CellStyle{contracts::CellStyle{foreground:render_color(s.fg),background:render_color(s.bg),bold:s.flags.bold,faint:s.flags.dim,italic:s.flags.italic,underline:s.flags.underline,inverse:s.flags.reverse,strikethrough:s.flags.strike}}
fn render_color(c:Color)->contracts::CellColor{match c{Color::Default=>contracts::CellColor::Default,Color::Indexed(x)=>contracts::CellColor::Indexed(x),Color::Rgb{r,g,b}=>contracts::CellColor::Rgb{red:r,green:g,blue:b}}}
pub fn write_full_snapshot(snapshot:&contracts::RenderSnapshot,out:&mut impl Write)->std::io::Result<()> {snapshot.validate().map_err(|_|std::io::Error::new(std::io::ErrorKind::InvalidInput,"invalid snapshot"))?;out.write_all(b"\x1b[?2026h\x1b[?25l\x1b[?6l\x1b[4l\x1b[?7l\x1b[0m\x1b[H\x1b[2J")?;for r in 0..snapshot.dimensions.rows{write!(out,"\x1b[{};1H",r+1)?;for c in 0..snapshot.dimensions.columns{let cell=&snapshot.cells[r as usize*snapshot.dimensions.columns as usize+c as usize];match cell.kind{contracts::CellKind::Blank=>out.write_all(b" ")?,contracts::CellKind::Single|contracts::CellKind::Wide=>out.write_all(&cell.text)?,contracts::CellKind::Continuation=>{}}}}write!(out,"\x1b[{};{}H",snapshot.cursor.row+1,snapshot.cursor.column+1)?;out.write_all(if snapshot.cursor.visible{b"\x1b[?25h"}else{b"\x1b[?25l"})?;out.write_all(b"\x1b[?2026l")}

#[cfg(test)]mod tests{use super::*;#[test]fn plain_writes(){let mut g=Grid::init(5,2).unwrap();g.feed(b"abc").unwrap();assert_eq!(g.row_text_trimmed(1),b"abc")}#[test]fn cup_and_erase(){let mut g=Grid::init(5,2).unwrap();g.feed(b"abc\x1b[1;2H\x1b[K").unwrap();assert_eq!(g.row_text_trimmed(1),b"a")}#[test]fn newline_scroll(){let mut g=Grid::init(2,2).unwrap();g.feed(b"a\nb\nc").unwrap();assert_eq!(g.row_text_trimmed(2),b"c")}#[test]fn checkpoint_roundtrip(){let mut g=Grid::init(4,2).unwrap();g.feed("a界".as_bytes()).unwrap();let p=g.checkpoint_payload().unwrap();assert_eq!(Grid::restore_checkpoint(&p).unwrap().snapshot(),g.snapshot())}#[test]fn sgr(){let mut g=Grid::init(3,1).unwrap();g.feed(b"\x1b[31mx").unwrap();assert_eq!(g.cell_at(1,1).unwrap().style.fg,Color::Indexed(1))}}
